#!/usr/bin/env python3
import pathlib, sys

lines = sys.stdin.read().splitlines()
if not lines or lines[0] != '*** Begin Patch' or lines[-1] != '*** End Patch':
    sys.exit('apply_patch: expected Begin/End Patch markers')
i = 1
while i < len(lines) - 1:
    header = lines[i]
    if header.startswith('*** Update File: '):
        path = pathlib.Path(header[len('*** Update File: '):])
        original = path.read_text().splitlines(keepends=True)
        output = original[:]
        i += 1
        search_from = 0
        while i < len(lines) - 1 and not lines[i].startswith('*** '):
            if not lines[i].startswith('@@'):
                sys.exit(f'apply_patch: expected hunk for {path}, got {lines[i]!r}')
            i += 1
            hunk = []
            while i < len(lines) - 1 and not lines[i].startswith('@@') and not lines[i].startswith('*** '):
                hunk.append(lines[i])
                i += 1
            old = [(line[1:] + '\n') for line in hunk if line and line[0] in ' -']
            new = [(line[1:] + '\n') for line in hunk if line and line[0] in ' +']
            if any(not line or line[0] not in ' +-' for line in hunk):
                sys.exit(f'apply_patch: malformed hunk for {path}')
            found = -1
            for start in range(search_from, len(output) - len(old) + 1):
                if output[start:start + len(old)] == old:
                    found = start
                    break
            if found < 0:
                sys.exit(f'apply_patch: hunk context not found in {path}: {old[:3]}')
            output[found:found + len(old)] = new
            search_from = found + len(new)
        path.write_text(''.join(output))
    elif header.startswith('*** Add File: '):
        path = pathlib.Path(header[len('*** Add File: '):])
        i += 1
        content = []
        while i < len(lines) - 1 and not lines[i].startswith('*** '):
            line = lines[i]
            if not line.startswith('+'):
                sys.exit(f'apply_patch: malformed add for {path}')
            content.append(line[1:] + '\n')
            i += 1
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(''.join(content))
    else:
        sys.exit(f'apply_patch: unsupported directive {header!r}')
